// Next working day (skips Sunday) in IST + firm configuration
const d = $now.setZone('Asia/Kolkata').plus({ days: 1 });
const t = d.weekday === 7 ? d.plus({ days: 1 }) : d;
return [{ json: {
  hearing_date_iso: t.toFormat('yyyy-LL-dd'),
  hearing_date_display: t.toFormat('cccc, dd LLL yyyy'),
  DD: t.toFormat('dd'), MM: t.toFormat('LL'), YYYY: t.toFormat('yyyy'),
  court_start: '10:30',               // court sitting time
  avg_minutes_per_item: 5,            // used to estimate call time from item no.
  clash_window_min: 60,               // same advocate, different hall within this window = clash
  admin_telegram_chat_id: 'REPLACE_WITH_ADMIN_TELEGRAM_CHAT_ID',
  partner_telegram_chat_id: 'REPLACE_WITH_PARTNER_TELEGRAM_CHAT_ID',
  outcome_form_url: 'REPLACE_WITH_N8N_BASE_URL/form/hearing-outcome',
  run_at: $now.toISO()
}}];

// One fetch job per court that actually has active matters
const d = $('Compute Next Hearing Date & Config').first().json;
const cases = $('Read Active Cases').all().map(i => i.json);
const used = new Set(cases.map(c => String(c.court_code || '').trim()));
const out = [];
for (const { json: c } of $input.all()) {
  const code = String(c.court_code || '').trim();
  if (!code || !used.has(code)) continue;
  if (String(c.active ?? 'yes').toLowerCase() === 'no') continue;
  const url = String(c.cause_list_url || '')
    .replace(/\{DD\}/g, d.DD).replace(/\{MM\}/g, d.MM)
    .replace(/\{YYYY\}/g, d.YYYY).replace(/\{DATE_ISO\}/g, d.hearing_date_iso);
  if (!url) continue;
  out.push({ json: { court_code: code, court_name: c.court_name || code, url,
    format: String(c.format || 'pdf').toLowerCase().includes('htm') ? 'html' : 'pdf' } });
}
return out;

