// Normalise cause-list text, locate every firm case, and detect listing stage
const d = $('Compute Next Hearing Date & Config').first().json;
const cases = $('Read Active Cases').all().map(i => i.json);
const norm = s => String(s || '').toUpperCase().replace(/[.\u00A0]/g, ' ').replace(/[ \t]+/g, ' ');
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const STAGES = [
  [/PART[\s-]?HEARD/, 'Part-heard'], [/FOR ORDERS|ORDERS ON/, 'Orders'], [/FINAL HEARING|FOR HEARING|REGULAR HEARING/, 'Final Hearing'],
  [/FRESH (MATTERS|CASES|ADMISSION)/, 'Fresh / Admission'], [/ADMISSION/, 'Admission'], [/MENTION/, 'Mention'],
  [/INTERLOCUTORY|\bI ?A\b/, 'Interlocutory Application'], [/JUDGMENT|PRONOUNCEMENT/, 'Judgment']
];
const items = $input.all();
const seen = new Set();
const out = [];

for (let i = 0; i < items.length; i++) {
  let court = {};
  try { court = $('Build Cause List Fetch List').itemMatching(i).json; } catch (e) { continue; }
  if (!court.court_code) continue;
  let raw = String(items[i].json.text ?? items[i].json.data ?? '');
  if (court.format === 'html') {
    raw = raw.replace(/<br\s*\/?>/gi, '\n').replace(/<\/(tr|p|div|li|h\d)>/gi, '\n')
             .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
  }
  const lines = norm(raw).split(/\r?\n/);

  for (const c of cases.filter(x => String(x.court_code).trim() === court.court_code)) {
    if (seen.has(c.case_id)) continue;
    const type = norm(c.case_type).replace(/[^A-Z]/g, '');
    const num = String(c.case_number || '').replace(/\D/g, '');
    const yr = String(c.case_year || '').replace(/\D/g, '');
    if (!type || !num || !yr) continue;
    const typePat = type.split('').map(esc).join('[\\s.()\\-]*');
    const re = new RegExp(`\\b${typePat}[\\s.()A-Z\\-]{0,12}?0*${num}\\s*(?:\\/|OF|-)\\s*${yr}\\b`);
    const hit = lines.findIndex(l => re.test(l));
    const base = {
      case_id: c.case_id, case_ref: `${c.case_type} ${c.case_number}/${c.case_year}`,
      case_title: c.case_title || '', client_name: c.client_name || '',
      court_code: court.court_code, court_name: court.court_name,
      advocate_name: c.advocate_name || '', advocate_whatsapp: String(c.advocate_whatsapp || '').replace(/\D/g, ''),
      advocate_telegram_chat_id: c.advocate_telegram_chat_id || '',
      preferred_channel: String(c.preferred_channel || 'telegram').toLowerCase().includes('whats') ? 'whatsapp' : 'telegram',
      hearing_date: d.hearing_date_iso, hearing_date_display: d.hearing_date_display,
      log_key: `${c.case_id}_${d.hearing_date_iso}`
    };
    if (hit >= 0) {
      seen.add(c.case_id);
      let itemNo = '', hall = '', bench = '', stage = '';
      for (let k = hit; k >= Math.max(0, hit - 3); k--) {
        const m = lines[k].match(/^\s*(\d{1,4})[\s.)]/); if (m) { itemNo = m[1]; break; }
      }
      for (let k = hit; k >= 0 && (!hall || !bench || !stage); k--) {
        if (!hall) { const m = lines[k].match(/COURT\s*(?:HALL|ROOM)?\s*(?:NO)?\s*[:.\-]?\s*(\d+[A-Z]?)\b/); if (m) hall = m[1]; }
        if (!bench && /HON'?BLE|JUSTICE|JUDGE/.test(lines[k])) bench = lines[k].trim().slice(0, 140);
        if (!stage && k < hit) { const s = STAGES.find(([r]) => r.test(lines[k])); if (s) stage = s[1]; }
      }
      out.push({ json: { ...base, listed: true, item_no: itemNo, court_hall: hall, bench, stage: stage || 'Not stated',
        matched_line: lines[hit].trim().slice(0, 200) } });
    } else if (String(c.next_hearing_date || '').slice(0, 10) === d.hearing_date_iso) {
      out.push({ json: { ...base, listed: false } });
    }
  }
}
return out;

const cfg = $('Compute Next Hearing Date & Config').first().json;
const matches = $('Match Cases to Cause List').all().map(i => i.json).filter(m => m.case_id);
const log = $input.all().map(i => i.json).filter(r => r.log_key);
const reminded = new Set(log.filter(r => String(r.reminder_sent).toLowerCase() === 'yes').map(r => r.log_key));
const [sh, sm] = String(cfg.court_start).split(':').map(Number);
const eta = n => {
  if (!n) return { mins: null, label: 'unknown' };
  const mins = sh * 60 + sm + (Number(n) - 1) * cfg.avg_minutes_per_item;
  const h = Math.floor(mins / 60), m = mins % 60;
  return { mins, label: `~${(h % 12) || 12}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}` };
};

const listed = matches.filter(m => m.listed).map(m => {
  const e = eta(m.item_no);
  return { ...m, est_minutes: e.mins, est_time: e.label,
    past_hearings: log.filter(r => r.case_id === m.case_id && r.hearing_date !== m.hearing_date).length };
});

// Clash detection: same advocate, different court/hall, overlapping estimated slots
const byAdv = {};
listed.forEach(m => { const k = m.advocate_name.trim().toLowerCase(); if (k) (byAdv[k] = byAdv[k] || []).push(m); });
for (const list of Object.values(byAdv)) {
  for (const m of list) {
    const clashes = list.filter(o => o !== m && (o.court_code !== m.court_code || o.court_hall !== m.court_hall) &&
      (m.est_minutes === null || o.est_minutes === null || Math.abs(o.est_minutes - m.est_minutes) <= cfg.clash_window_min));
    m.clash = clashes.map(o => `${o.case_ref} @ ${o.court_name}${o.court_hall ? ' CH ' + o.court_hall : ''} ${o.est_time}`).join('; ');
    m.matters_tomorrow = list.length;
  }
}

const out = [
  ...listed.map(m => ({ json: { ...m, route: reminded.has(m.log_key) ? 'skip' : 'remind' } })),
  ...matches.filter(m => !m.listed).map(m => ({ json: { ...m, route: 'not_listed' } }))
];
return out.length ? out : [{ json: { route: 'none' } }];

const cfg = $('Compute Next Hearing Date & Config').first().json;
const all = $input.all().map(i => i.json).filter(x => x.route && x.route !== 'none');
const listed = all.filter(x => x.listed).sort((a, b) => (a.est_minutes ?? 9999) - (b.est_minutes ?? 9999));
const missing = all.filter(x => x.route === 'not_listed');
let failed = 0; try { failed = $('Alert Admin: Fetch Failed').all().length; } catch (e) {}
const byAdv = {};
listed.forEach(m => (byAdv[m.advocate_name || 'Unassigned'] = byAdv[m.advocate_name || 'Unassigned'] || []).push(m));
const seenPair = new Set();
const clashes = listed.filter(m => { if (!m.clash) return false; const k = [m.advocate_name, ...listed.filter(o => o.advocate_name === m.advocate_name && o.clash).map(o => o.case_id).sort()].join('|'); if (seenPair.has(k)) return false; seenPair.add(k); return true; });
const lines = [
  `📋 Cause List Board – ${cfg.hearing_date_display}`,
  `${listed.length} matter(s) listed · ${Object.keys(byAdv).length} advocate(s) · ${clashes.length ? '⚠️ ' + clashes.length + ' clash(es)' : 'no clashes'}`, '',
  ...Object.entries(byAdv).flatMap(([adv, ms]) => [`👤 ${adv} (${ms.length})`,
    ...ms.map(m => `  • ${m.case_ref} – ${m.court_name}${m.court_hall ? ' CH ' + m.court_hall : ''} · Item ${m.item_no || '?'} · ${m.est_time} · ${m.stage}`)]),
  ...(clashes.length ? ['', '🔀 Clashes (arrange proxy / pass-over):', ...clashes.map(m => `  • ${m.advocate_name}: ${m.case_ref} vs ${m.clash}`)] : []),
  ...(missing.length ? ['', '❓ Expected but not listed:', ...missing.map(m => `  • ${m.case_ref} (${m.court_name}) – ${m.advocate_name}`)] : []),
  ...(failed ? ['', `❌ ${failed} cause list(s) could not be fetched. Check them manually.`] : []),
  ...(!listed.length && !missing.length ? ['No firm matters in tomorrow\'s cause lists.'] : [])
];
return [{ json: { chat_id: cfg.partner_telegram_chat_id, text: lines.join('\n').slice(0, 4000) } }];

