const c = $('Loop Over Hearings').first().json;
const cfg = $('Compute Next Hearing Date & Config').first().json;
const ai = $input.first().json.output || {};
const checklist = Array.isArray(ai.prep_checklist) ? ai.prep_checklist : [];
const lines = [
  `⚖️ *Hearing tomorrow* – ${c.hearing_date_display}`,
  `*${c.case_ref}*${c.case_title ? ' – ' + c.case_title : ''}`,
  `Client: ${c.client_name || '-'}`,
  `Court: ${c.court_name}${c.court_hall ? ' · Court Hall ' + c.court_hall : ''}`,
  `Item ${c.item_no || '?'} · ${c.est_time} · ${c.stage}`,
  c.bench ? `Bench: ${c.bench}` : null,
  ai.listing_purpose ? `\n🎯 ${ai.listing_purpose}` : null,
  ai.last_hearing_recap ? `🕘 Last: ${ai.last_hearing_recap}` : null,
  checklist.length ? `\n📝 *Prep*\n${checklist.map(x => '• ' + x).join('\n')}` : null,
  ai.watch_out ? `\n⚠️ ${ai.watch_out}` : null,
  c.clash ? `\n🔀 *CLASH:* also listed – ${c.clash}${ai.clash_advice ? '\n➜ ' + ai.clash_advice : ''}` : null,
  `\nAfter the hearing, log the outcome and next date: ${cfg.outcome_form_url}`
].filter(x => x !== null);
const wa_text = lines.join('\n');
return [{ json: { ...c, wa_text, tg_text: wa_text.replace(/\*/g, ''), prep_checklist: checklist.join(' | '),
  listing_purpose: ai.listing_purpose || '' } }];

const FORM_URL = 'REPLACE_WITH_N8N_BASE_URL/form/hearing-outcome';
const rows = $input.all().map(i => i.json).filter(r => r.case_id && !r.outcome);
const toMin = s => { const m = String(s || '').match(/(\d+):(\d+)\s*(AM|PM)/); if (!m) return 9999;
  let h = Number(m[1]) % 12; if (m[3] === 'PM') h += 12; return h * 60 + Number(m[2]); };
const groups = {};
rows.forEach(r => (groups[r.advocate_name || 'Unassigned'] = groups[r.advocate_name || 'Unassigned'] || []).push(r));
return Object.entries(groups).map(([adv, list]) => {
  list.sort((a, b) => toMin(a.est_time) - toMin(b.est_time));
  const text = [`☀️ *Today's board – ${adv}* (${list.length} matter${list.length > 1 ? 's' : ''})`, '',
    ...list.map((r, i) => `${i + 1}. ${r.est_time} · ${r.court_name}${r.court_hall ? ' CH ' + r.court_hall : ''} · Item ${r.item_no || '?'}\n   *${r.case_ref}* · ${r.stage || ''}${r.clash ? '\n   🔀 Clash noted' : ''}`),
    '', `📝 Log outcomes after each hearing: ${FORM_URL}`].join('\n');
  const first = list[0];
  return { json: { advocate: adv, channel: String(first.channel || 'telegram').toLowerCase(),
    whatsapp: first.advocate_whatsapp, telegram: first.advocate_telegram_chat_id,
    wa_text: text, tg_text: text.replace(/\*/g, '') } };
});

const f = $json;
const caseId = String(f['Case ID'] || '').trim();
const hd = String(f['Hearing Date'] || '').slice(0, 10);
const outcome = f['Outcome'];
const next = String(f['Next Hearing Date'] || '').slice(0, 10);
const closing = ['Disposed', 'Withdrawn'].includes(outcome);
const reserved = outcome === 'Heard – Judgment Reserved';
const flags = [];
if (!closing && !reserved && !next) flags.push('Next date missing. Please update it.');
if (next && next <= hd) flags.push('Next date is not after the hearing date');
return { json: {
  log_key: `${caseId}_${hd}`, case_id: caseId, hearing_date: hd, outcome,
  next_date: next, case_next_date: closing ? '' : (next || (reserved ? 'Reserved' : 'TBD')),
  case_status: closing ? 'Closed' : 'Active', order_summary: f['Order / Proceedings Summary'] || '',
  advocate: f['Advocate Name'], flags: flags.join('; '), logged_at: new Date().toISOString() } };

